import { DigoAsset } from '@digo-org/digo-api';
import React, { useRef, useEffect, useState, useCallback } from 'react';
import * as d3 from 'd3';

interface VaccineData {
  name: string;
  disease: string;
  efficacy: number;
  doses: number;
  year: number;
  type: string;
  index: number;
}

interface TooltipState {
  visible: boolean;
  x: number;
  y: number;
  data: VaccineData | null;
}

const DEFAULT_TYPE_COLORS: Record<string, string> = {
  'mrna': '#00e5ff',
  'viral vector': '#ff9100',
  'inactivated': '#00e676',
  'live attenuated': '#d500f9',
  'recombinant': '#ff4081',
  'conjugate': '#ffea00',
};

interface RadialChartProps {
  instances: any[];
  globalParameters: Record<string, any>;
}

function RadialChart({ instances, globalParameters }: RadialChartProps) {
  const svgRef = useRef<SVGSVGElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [tooltip, setTooltip] = useState<TooltipState>({ visible: false, x: 0, y: 0, data: null });
  const [dimensions, setDimensions] = useState({ width: 800, height: 800 });

  const bgColor = (globalParameters['background-color'] as string) || '#0a0e27';
  const textColor = (globalParameters['text-color'] as string) || '#e0e6ff';
  const showLabels = globalParameters['show-labels'] !== false;
  const showDoseIndicators = globalParameters['show-dose-indicators'] !== false;
  const showYearRing = globalParameters['show-year-ring'] !== false;
  const animDuration = (globalParameters['animation-duration'] as number) ?? 1200;
  const innerRadiusPct = (globalParameters['inner-radius'] as number) ?? 25;
  const outerScale = (globalParameters['outer-radius-scale'] as number) ?? 80;
  const labelFontSize = (globalParameters['label-font-size'] as number) ?? 11;

  const typeColors: Record<string, string> = {
    'mrna': (globalParameters['color-mrna'] as string) || DEFAULT_TYPE_COLORS['mrna'],
    'viral vector': (globalParameters['color-viral-vector'] as string) || DEFAULT_TYPE_COLORS['viral vector'],
    'inactivated': (globalParameters['color-inactivated'] as string) || DEFAULT_TYPE_COLORS['inactivated'],
    'live attenuated': (globalParameters['color-live-attenuated'] as string) || DEFAULT_TYPE_COLORS['live attenuated'],
    'recombinant': (globalParameters['color-recombinant'] as string) || DEFAULT_TYPE_COLORS['recombinant'],
    'conjugate': (globalParameters['color-conjugate'] as string) || DEFAULT_TYPE_COLORS['conjugate'],
  };

  const getTypeColor = (type: string): string => {
    const key = type?.toLowerCase().trim() || '';
    if (typeColors[key]) return typeColors[key];
    const match = Object.keys(typeColors).find(k => key.startsWith(k) || key.includes(k));
    return match ? typeColors[match] : '#888888';
  };

  useEffect(() => {
    const observer = new ResizeObserver(entries => {
      for (const entry of entries) {
        const { width, height } = entry.contentRect;
        setDimensions({ width: Math.max(width, 400), height: Math.max(height, 400) });
      }
    });
    if (containerRef.current) observer.observe(containerRef.current);
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    if (!svgRef.current || !instances || instances.length === 0) return;

    const svg = d3.select(svgRef.current);
    svg.selectAll('*').remove();

    const { width, height } = dimensions;
    const cx = width / 2;
    const cy = height / 2;
    const maxRadius = Math.min(cx, cy) - 60;
    const innerR = maxRadius * (innerRadiusPct / 100);
    const outerR = maxRadius * (outerScale / 100);

    const data: VaccineData[] = instances.map((inst: any, i: number) => ({
      ...inst,
      name: (inst['vaccine-name'] as string) || `Vaccine ${i + 1}`,
      disease: (inst['disease-targeted'] as string) || 'Unknown',
      efficacy: (inst['efficacy-rate'] as number) ?? 50,
      doses: Math.round((inst['doses-required'] as number) ?? 1),
      year: Math.round((inst['year-approved'] as number) ?? 2000),
      type: (inst['vaccine-type'] as string) || 'Unknown',
      index: i,
    }));

    const n = data.length;
    const angleSlice = (2 * Math.PI) / n;
    const padAngle = 0.03;

    const defs = svg.append('defs');

    // Glow filter
    const glowFilter = defs.append('filter').attr('id', 'glow').attr('x', '-50%').attr('y', '-50%').attr('width', '200%').attr('height', '200%');
    glowFilter.append('feGaussianBlur').attr('stdDeviation', '4').attr('result', 'coloredBlur');
    const glowMerge = glowFilter.append('feMerge');
    glowMerge.append('feMergeNode').attr('in', 'coloredBlur');
    glowMerge.append('feMergeNode').attr('in', 'SourceGraphic');

    // Soft glow for hover
    const hoverGlow = defs.append('filter').attr('id', 'hover-glow').attr('x', '-50%').attr('y', '-50%').attr('width', '200%').attr('height', '200%');
    hoverGlow.append('feGaussianBlur').attr('stdDeviation', '8').attr('result', 'coloredBlur');
    const hoverMerge = hoverGlow.append('feMerge');
    hoverMerge.append('feMergeNode').attr('in', 'coloredBlur');
    hoverMerge.append('feMergeNode').attr('in', 'SourceGraphic');

    // Radial gradient for background
    const bgGrad = defs.append('radialGradient').attr('id', 'bg-gradient').attr('cx', '50%').attr('cy', '50%').attr('r', '60%');
    bgGrad.append('stop').attr('offset', '0%').attr('stop-color', d3.color(bgColor)?.brighter(0.5)?.toString() || '#151b3d');
    bgGrad.append('stop').attr('offset', '100%').attr('stop-color', bgColor);

    // Create gradients for each vaccine type
    Object.entries(typeColors).forEach(([type, color]) => {
      const id = 'grad-' + type.replace(/\s+/g, '-');
      const grad = defs.append('radialGradient').attr('id', id).attr('gradientUnits', 'userSpaceOnUse').attr('cx', 0).attr('cy', 0).attr('r', outerR);
      grad.append('stop').attr('offset', `${(innerR / outerR * 100).toFixed(1)}%`).attr('stop-color', color).attr('stop-opacity', 0.2);
      grad.append('stop').attr('offset', '100%').attr('stop-color', color).attr('stop-opacity', 0.95);
    });

    const g = svg.append('g').attr('transform', `translate(${cx},${cy})`);

    // Background circle with subtle radial gradient
    g.append('circle').attr('r', outerR + 30).attr('fill', 'url(#bg-gradient)').attr('opacity', 0.3);

    // Grid circles
    const gridLevels = [25, 50, 75, 100];
    const efficacyScale = d3.scaleLinear().domain([0, 100]).range([innerR, outerR]);

    gridLevels.forEach(level => {
      g.append('circle')
        .attr('r', efficacyScale(level))
        .attr('fill', 'none')
        .attr('stroke', textColor)
        .attr('stroke-opacity', 0.08)
        .attr('stroke-dasharray', '3,5');
      g.append('text')
        .attr('x', 4)
        .attr('y', -efficacyScale(level))
        .attr('fill', textColor)
        .attr('fill-opacity', 0.3)
        .attr('font-size', 9)
        .attr('font-family', 'monospace')
        .text(`${level}%`);
    });

    // Year ring
    const yearExtent = d3.extent(data, d => d.year) as [number, number];

    if (showYearRing) {
      const yearScale = d3.scaleLinear().domain(yearExtent).range([0.25, 1]);
      const yearRingR = innerR - 15;

      data.forEach((d, i) => {
        const startAngle = i * angleSlice - Math.PI / 2;
        const endAngle = startAngle + angleSlice - padAngle;
        const arc = d3.arc<any>().innerRadius(yearRingR - 6).outerRadius(yearRingR).startAngle(startAngle).endAngle(endAngle).padAngle(0.02);
        g.append('path')
          .attr('d', arc({}) || '')
          .attr('fill', getTypeColor(d.type))
          .attr('opacity', 0)
          .transition()
          .delay(animDuration * 0.8 + i * 40)
          .duration(400)
          .attr('opacity', yearScale(d.year) * 0.6);
      });
    }

    // Central hub
    const hubR = innerR - (showYearRing ? 28 : 12);
    const hubGrad = defs.append('radialGradient').attr('id', 'hub-grad').attr('cx', '50%').attr('cy', '40%').attr('r', '60%');
    hubGrad.append('stop').attr('offset', '0%').attr('stop-color', '#2a3060');
    hubGrad.append('stop').attr('offset', '100%').attr('stop-color', '#0d1025');

    g.append('circle').attr('r', hubR).attr('fill', 'url(#hub-grad)').attr('stroke', textColor).attr('stroke-opacity', 0.15).attr('stroke-width', 1);
    g.append('text').attr('text-anchor', 'middle').attr('y', -8).attr('fill', textColor).attr('font-size', 13).attr('font-weight', '700').attr('font-family', 'Inter, system-ui, sans-serif').attr('letter-spacing', '0.1em').text('VACCINE');
    g.append('text').attr('text-anchor', 'middle').attr('y', 10).attr('fill', textColor).attr('fill-opacity', 0.6).attr('font-size', 10).attr('font-family', 'Inter, system-ui, sans-serif').attr('letter-spacing', '0.15em').text('EFFICACY');
    g.append('text').attr('text-anchor', 'middle').attr('y', 26).attr('fill', textColor).attr('fill-opacity', 0.35).attr('font-size', 8).attr('font-family', 'monospace').text(`${n} vaccines`);

    // Draw radial bars
    const barGroups = g.selectAll('.bar-group').data(data).enter().append('g').attr('class', 'bar-group').style('cursor', 'pointer');

    barGroups.each(function (d, i) {
      const group = d3.select(this);
      const startAngle = i * angleSlice - Math.PI / 2;
      const endAngle = startAngle + angleSlice - padAngle;
      const midAngle = (startAngle + endAngle) / 2;
      const barR = efficacyScale(d.efficacy);
      const color = getTypeColor(d.type);
      const typeKey = Object.keys(typeColors).find(k => d.type.toLowerCase().trim().startsWith(k) || d.type.toLowerCase().trim().includes(k)) || d.type.toLowerCase().trim();
      const gradId = 'grad-' + typeKey.replace(/\s+/g, '-');

      // Create arc for bar
      const barArc = d3.arc<any>().innerRadius(innerR).outerRadius(innerR).startAngle(startAngle + padAngle / 2).endAngle(endAngle - padAngle / 2).cornerRadius(3);
      const barArcFull = d3.arc<any>().innerRadius(innerR).outerRadius(barR).startAngle(startAngle + padAngle / 2).endAngle(endAngle - padAngle / 2).cornerRadius(3);

      // Background bar (faint)
      const bgArc = d3.arc<any>().innerRadius(innerR).outerRadius(outerR).startAngle(startAngle + padAngle / 2).endAngle(endAngle - padAngle / 2).cornerRadius(3);
      group.append('path').attr('d', bgArc({}) || '').attr('fill', color).attr('opacity', 0.04);

      // Main bar with animation
      const barPath = group.append('path')
        .attr('d', barArc({}) || '')
        .attr('fill', `url(#${gradId})`)
        .attr('stroke', color)
        .attr('stroke-width', 0.5)
        .attr('stroke-opacity', 0.5)
        .attr('filter', 'url(#glow)');

      barPath.transition()
        .delay(i * 60)
        .duration(animDuration)
        .ease(d3.easeElasticOut.amplitude(1).period(0.5))
        .attrTween('d', () => {
          const interp = d3.interpolate(innerR, barR);
          return (t: number) => {
            const r = interp(t);
            return d3.arc<any>().innerRadius(innerR).outerRadius(r).startAngle(startAngle + padAngle / 2).endAngle(endAngle - padAngle / 2).cornerRadius(3)({}) || '';
          };
        });

      // Bright cap at the top of each bar
      const capArc = d3.arc<any>().innerRadius(barR - 2).outerRadius(barR).startAngle(startAngle + padAngle / 2).endAngle(endAngle - padAngle / 2).cornerRadius(1);
      group.append('path')
        .attr('d', capArc({}) || '')
        .attr('fill', color)
        .attr('opacity', 0)
        .transition()
        .delay(i * 60 + animDuration * 0.8)
        .duration(300)
        .attr('opacity', 0.9);

      // Dose indicators
      if (showDoseIndicators) {
        const dosesCount = Math.min(d.doses, 5);
        const doseStartR = innerR + 8;
        const doseSpacing = Math.min(14, (barR - innerR - 16) / dosesCount);
        for (let di = 0; di < dosesCount; di++) {
          const dr = doseStartR + di * doseSpacing;
          const dx = Math.sin(midAngle) * dr;
          const dy = -Math.cos(midAngle) * dr;
          group.append('circle')
            .attr('cx', dx)
            .attr('cy', dy)
            .attr('r', 0)
            .attr('fill', '#ffffff')
            .attr('fill-opacity', 1)
            .attr('stroke', color)
            .attr('stroke-width', 1.2)
            .attr('stroke-opacity', 0.9)
            .transition()
            .delay(i * 60 + animDuration * 0.6 + di * 80)
            .duration(300)
            .ease(d3.easeBackOut)
            .attr('r', 2.8);
        }
      }

      // Vaccine name labels
      if (showLabels) {
        const labelR = outerR + 16;
        const lx = Math.sin(midAngle) * labelR;
        const ly = -Math.cos(midAngle) * labelR;
        const angleDeg = (midAngle * 180) / Math.PI - 90;
        const isRight = angleDeg > -90 && angleDeg < 90;
        const rotation = isRight ? angleDeg : angleDeg + 180;

        group.append('text')
          .attr('x', lx)
          .attr('y', ly)
          .attr('text-anchor', isRight ? 'start' : 'end')
          .attr('dominant-baseline', 'central')
          .attr('dy', '-0.5em')
          .attr('transform', `rotate(${rotation},${lx},${ly})`)
          .attr('fill', textColor)
          .attr('fill-opacity', 0)
          .attr('font-size', labelFontSize)
          .attr('font-family', 'Inter, system-ui, sans-serif')
          .attr('font-weight', '500')
          .text(d.name)
          .transition()
          .delay(i * 60 + animDuration * 0.9)
          .duration(400)
          .attr('fill-opacity', 0.85);

        // Disease subtitle
        group.append('text')
          .attr('x', lx)
          .attr('y', ly)
          .attr('dy', '1em')
          .attr('text-anchor', isRight ? 'start' : 'end')
          .attr('dominant-baseline', 'central')
          .attr('transform', `rotate(${rotation},${lx},${ly})`)
          .attr('fill', color)
          .attr('fill-opacity', 0)
          .attr('font-size', Math.max(labelFontSize - 3, 7))
          .attr('font-family', 'monospace')
          .attr('letter-spacing', '0.05em')
          .text(d.disease)
          .transition()
          .delay(i * 60 + animDuration * 0.95)
          .duration(400)
          .attr('fill-opacity', 0.5);
      }

      // Hover interactions
      const hoverOverlay = d3.arc<any>().innerRadius(innerR).outerRadius(outerR + 20).startAngle(startAngle).endAngle(endAngle);
      group.append('path')
        .attr('d', hoverOverlay({}) || '')
        .attr('fill', 'transparent')
        .attr('class', 'hover-zone')
        .on('mouseenter', function (event: MouseEvent) {
          barPath.attr('filter', 'url(#hover-glow)').transition().duration(200).attr('fill-opacity', 1).attr('stroke-width', 1.5);
          group.selectAll('text').transition().duration(200).attr('fill-opacity', 1);
          const rect = svgRef.current?.getBoundingClientRect();
          if (rect) {
            setTooltip({
              visible: true,
              x: event.clientX - rect.left,
              y: event.clientY - rect.top,
              data: d,
            });
          }
        })
        .on('mousemove', function (event: MouseEvent) {
          const rect = svgRef.current?.getBoundingClientRect();
          if (rect) {
            setTooltip(prev => ({ ...prev, x: event.clientX - rect.left, y: event.clientY - rect.top }));
          }
        })
        .on('mouseleave', function () {
          barPath.attr('filter', 'url(#glow)').transition().duration(300).attr('fill-opacity', 1).attr('stroke-width', 0.5);
          group.selectAll('text').filter(function () { return d3.select(this).attr('font-weight') !== '500'; }).transition().duration(300).attr('fill-opacity', 0.5);
          group.selectAll('text').filter(function () { return d3.select(this).attr('font-weight') === '500'; }).transition().duration(300).attr('fill-opacity', 0.85);
          setTooltip(prev => ({ ...prev, visible: false }));
        });
    });

    // Legend
    const legendHeight = Object.keys(typeColors).length * 22 + (showYearRing ? 55 : 0);
    const legendG = svg.append('g').attr('transform', `translate(20, ${height - legendHeight - 20})`);
    Object.entries(typeColors).forEach(([type, color], i) => {
      const row = legendG.append('g').attr('transform', `translate(0, ${i * 22})`).attr('opacity', 0);
      row.append('rect').attr('width', 12).attr('height', 12).attr('rx', 3).attr('fill', color).attr('opacity', 0.8);
      row.append('text').attr('x', 18).attr('y', 10).attr('fill', textColor).attr('fill-opacity', 0.7).attr('font-size', 10).attr('font-family', 'Inter, system-ui, sans-serif').text(type.charAt(0).toUpperCase() + type.slice(1));
      row.transition().delay(animDuration + i * 80).duration(400).attr('opacity', 1);
    });

    if (showYearRing) {
      const yearLegendY = Object.keys(typeColors).length * 22 + 20;
      const yearGroup = legendG.append('g').attr('transform', `translate(0, ${yearLegendY})`).attr('opacity', 0);
      const yearGradId = 'year-legend-grad';
      const yGrad = defs.append('linearGradient').attr('id', yearGradId);
      yGrad.append('stop').attr('offset', '0%').attr('stop-color', textColor).attr('stop-opacity', 0.12);
      yGrad.append('stop').attr('offset', '100%').attr('stop-color', textColor).attr('stop-opacity', 0.85);
      yearGroup.append('text').attr('fill', textColor).attr('fill-opacity', 0.65).attr('font-size', 9).attr('font-family', 'Inter, system-ui, sans-serif').attr('font-weight', '600').attr('letter-spacing', '0.05em').text('Inner Ring \u2014 Year Approved');
      yearGroup.append('rect').attr('y', 10).attr('width', 110).attr('height', 6).attr('rx', 3).attr('fill', `url(#${yearGradId})`);
      yearGroup.append('text').attr('y', 28).attr('fill', textColor).attr('fill-opacity', 0.45).attr('font-size', 8).attr('font-family', 'monospace').text(`${yearExtent[0]}`);
      yearGroup.append('text').attr('x', 110).attr('y', 28).attr('fill', textColor).attr('fill-opacity', 0.45).attr('font-size', 8).attr('font-family', 'monospace').attr('text-anchor', 'end').text(`${yearExtent[1]}`);
      yearGroup.append('text').attr('x', 55).attr('y', 28).attr('fill', textColor).attr('fill-opacity', 0.25).attr('font-size', 8).attr('font-family', 'monospace').attr('text-anchor', 'middle').text('\u2192');
      yearGroup.transition().delay(animDuration + Object.keys(typeColors).length * 80 + 120).duration(400).attr('opacity', 1);
    }

  }, [instances, globalParameters, dimensions]);

  return (
    <div ref={containerRef} style={{ width: '100%', height: '100%', position: 'relative', backgroundColor: bgColor, overflow: 'hidden' }}>
      <svg ref={svgRef} width={dimensions.width} height={dimensions.height} style={{ display: 'block' }} />
      {tooltip.visible && tooltip.data && (
        <div
          className="vaccine-tooltip"
          style={{
            position: 'absolute',
            left: tooltip.x + 16,
            top: tooltip.y - 10,
            pointerEvents: 'none',
            zIndex: 100,
            color: textColor,
          }}
        >
          <div className="tooltip-header" style={{ color: getTypeColor(tooltip.data.type) }}>
            {tooltip.data.name}
          </div>
          <div className="tooltip-row"><span className="tooltip-label">Disease:</span> {tooltip.data.disease}</div>
          <div className="tooltip-row"><span className="tooltip-label">Efficacy:</span> {tooltip.data.efficacy.toFixed(1)}%</div>
          <div className="tooltip-row"><span className="tooltip-label">Doses:</span> {'\u25CF '.repeat(tooltip.data.doses).trim()}</div>
          <div className="tooltip-row"><span className="tooltip-label">Approved:</span> {tooltip.data.year}</div>
          <div className="tooltip-row"><span className="tooltip-label">Type:</span>
            <span style={{ color: getTypeColor(tooltip.data.type), fontWeight: 600 }}> {tooltip.data.type}</span>
          </div>
        </div>
      )}
    </div>
  );
}

export class Asset extends DigoAsset {
  constructor() {
    super();
  }

  render() {
    return (
      <RadialChart
        instances={this.instances || []}
        globalParameters={this.globalParameters || {}}
      />
    );
  }
}

